import{z as l,x as o,o as r,c as d,q as B,j as n,D as t,d as E,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"对照案例与收束","description":"","frontmatter":{"title":"对照案例与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gm-case-map.md","filePath":"quant/gm-case-map.md","lastUpdated":1791063341000}'),p={name:"quant/gm-case-map.md"};function m(u,a,F,h,c,D){const A=o("Mermaid");return r(),d("div",null,[a[2]||(a[2]=B('<h1 id="对照案例与收束" tabindex="-1">对照案例与收束 <a class="header-anchor" href="#对照案例与收束" aria-label="Permalink to &quot;对照案例与收束&quot;">​</a></h1><div class="epigraph"><p>策略不是公式，是公式加一套制度假设；迁移失败很少死于信号失效，多数死于把环境常量当成了普适真理——收束就是把常量清单写出来，标上日期。</p><footer>—— 据 Harris, Trading and Exchanges, 2003；Foucault, Pagano and Röell, Market Liquidity, 2013 及本课程各课整理</footer></div><p><a href="/quant/gm-arb-constraints">上一课</a>把跨市场价差翻译成七项摩擦清单，判断「机会还是状态」。本课是全球市场制度对照的收束：前九课每课产出一张市场或机制的清单，本课把它们并成一张迁移前检查单与两个迁移案例，回答最后的问题——策略进新市场，先查什么、按什么顺序查。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>十个市场的课读下来，条目很多，但检查的顺序只有一个：按钱的顺序。先问可不可交易（通道、许可、卖空的可得性——做不了，后面全免）；再问贵不贵（费用与税的税后账——做得了但亏，也免）；再问稳不稳（结算、熔断、数据口径——能盈利的账要在后链成立）；最后问久不久（制度参数何时变过——历史绩效的样本要按制度断点切）。缺口在于真实流程常常倒着走：先看绩效图，再补合规，税费在上线当周才算清。倒序的成本与前两课的复盘口径相同：错误在第一周可见，只是没人被要求去看。</p><p><span class="marginnote">「按钱的顺序」可以想象成入境检查：先看签证让不让你进（可交易性），再看行李要不要交税（成本），再看当地 交通规则左行右行（后链稳定性），最后翻史书确认规则哪年改过（制度断点）。顺序颠倒的代价是：签证被拒的人，早就把行李税和交规背完了。</span></p><p><span class="marginnote">制度变更日是事件日：印花税调整、结算周期迁移、撮合引擎更换——把参数更新静默写进数据，等于让回测在不存在的制度里跑；每个清单项都要能回答「这一格上次是什么、何时变的」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>收束成三张表。第一张是维度表：行是维度（会话与时钟、tick 与手数、价格限制与熔断族、卖空制度、费用与税、清算与结算、数据与披露、合规报备），列是市场（美国、欧洲、日本、香港、印度、加密），每格一句话并指回对应课——美国格写订单保护与 <a href="/quant/market-fragmentation">市场分割与 NBBO</a> 的参照口径，欧洲格写最佳执行与豁免，日本格写午休与値幅制，香港格写收市竞价 VCM 与双边印花税，印度格写 T+1 与交付拍卖，加密格写无保护与托管对手。第二张是案例表：两个小案例走一遍顺序——高频做市从美股到港股，第一关就是税负敏感性（<a href="/quant/gm-tax-costs">税与交易成本</a>的双边印花税排序翻转），顺序对了当天放弃、学费是一份测试；统计套利从美股到印度，卡在卖空可执行性（<a href="/quant/gm-india">印度市场</a>的 SLB 与拍卖惩罚），空腿重建后再谈容量。第三张是失败模式表：订单保护幻觉（把美国的保护当成普适）、税后排序不重算（把税前列当结论）、结算日历敞口（把配对簿的周期差当零）——每条死法都能在前九课找到机制出处。</p>',9)),(r(),n(s,null,{default:t(()=>[i(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E7%AD%96%E7%95%A5%E8%BF%81%E7%A7%BB%E6%96%B0%E5%B8%82%E5%9C%BA%22%5D%20--%3E%20Q1%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E6%80%A7%EF%BC%9A%E9%80%9A%E9%81%93%2F%E8%AE%B8%E5%8F%AF%2F%E5%8D%96%E7%A9%BA%22%5D%0A%20%20Q1%20--%3E%20Q2%5B%22%E6%88%90%E6%9C%AC%EF%BC%9A%E7%A8%8E%E5%90%8E%E8%B4%A6%E9%87%8D%E6%8E%92%22%5D%0A%20%20Q2%20--%3E%20Q3%5B%22%E7%A8%B3%E5%AE%9A%E6%80%A7%EF%BC%9A%E7%BB%93%E7%AE%97%2F%E7%86%94%E6%96%AD%2F%E6%95%B0%E6%8D%AE%E5%8F%A3%E5%BE%84%22%5D%0A%20%20Q3%20--%3E%20Q4%5B%22%E6%96%AD%E7%82%B9%EF%BC%9A%E5%88%B6%E5%BA%A6%E5%8F%98%E6%9B%B4%E6%97%A5%E5%88%87%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20Q4%20--%3E%20REG%5B%22%E5%8F%B0%E8%B4%A6%E5%BD%92%E6%A1%A3%EF%BC%9A%E6%AF%8F%E6%A0%BC%E5%B8%A6%E6%97%A5%E6%9C%9F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("对照表的机制价值在于把「环境常量」显式化：微观结构课程教的是在给定制度下如何交易，本课程教的是制度本身如何给定。环境常量改变时，历史绩效的预测力以断点为界——引擎迁移、印花税调整、结算周期变更、监管框架落地，每一处都是样本的分段点；回测按断点切、参数按当期读，绩效报告必须能指认「这段绩效是在哪套制度参数下生成的」。这与"),e("a",{href:"/quant/gm-us-structure"},"美国市场结构"),E("一课对数据口径（SIP 与直连）的声明是同一种纪律：制度口径不声明，绩效数字没有解释。不这么做会错在哪：把六套制度压成一个「国际市场」假设，组合里每个市场各漏一笔账，压力日一起兑付——摩擦有相关性，因为它们同源（资本、清算、税制的联动）。")],-1)),a[5]||(a[5]=e("p",null,"制度断点如何把一条回测切成可引用的段，回答的是「绩效数字该挂在哪套参数下」：",-1)),(r(),n(s,null,{default:t(()=>[i(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20Hist%5B%22%E5%8E%9F%E5%A7%8B%E5%8E%86%E5%8F%B2%E7%BB%A9%E6%95%88%20%E4%B8%80%E6%95%B4%E6%9D%A1%22%5D%20--%3E%20EV%5B%22%E5%88%B6%E5%BA%A6%E5%8F%98%E6%9B%B4%E6%97%A5%20%E5%88%97%E5%87%BA%E6%96%AD%E7%82%B9%22%5D%0A%20%20EV%20--%3E%20A%5B%22%E6%AE%B5A%20%E6%97%A7%E5%8F%82%E6%95%B0%E4%B8%8B%E7%9A%84%E7%BB%A9%E6%95%88%22%5D%0A%20%20EV%20--%3E%20B%5B%22%E6%AE%B5B%20%E6%96%B0%E5%8F%82%E6%95%B0%E4%B8%8B%E7%9A%84%E7%BB%A9%E6%95%88%22%5D%0A%20%20A%20--%3E%20Note%5B%22%E6%A0%87%E6%B3%A8%E7%94%9F%E6%88%90%E5%8F%A3%E5%BE%84%E5%90%8E%E5%BD%92%E6%A1%A3%22%5D%0A%20%20B%20--%3E%20Cur%5B%22%E5%8F%AA%E6%9C%89%E6%AE%B5B%E5%8F%AF%E5%A4%96%E6%8E%A8%E5%88%B0%E5%BD%93%E4%B8%8B%22%5D%0A%20%20Cur%20--%3E%20Read%5B%22%E5%8F%82%E6%95%B0%E6%8C%89%E5%BD%93%E6%9C%9F%E6%96%87%E6%9C%AC%E9%87%8D%E8%AF%BB%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">数字实例：一个 2018–2026 年的港股策略回测，若 2021 年印花税双边调升、2023 年结算规则变更，就该至少切成三段。整条算下来年化 8%，可能其中旧参数段贡献 12%、当期参数段只有 5%——不做切分，你外推用的是那个并不存在的 8%。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本表是快照：税率、周期、带值与监管框架滚动变化，表格必须带生成日期，任何一格失效都按当期文本重读而非凭记忆修订。本课程不给合规与法律意见；跨境运营的许可问题在通道课只写了「先核通道」，具体申请不在口径内。深钻层到此为止，制度对照不接附录。</p><p><span class="marginnote">常见误区：初学者容易把课程或表格里的参数当成永久事实，例如记住「印度是 T+1」就不再核对。实际上制度参数是有出生日期的数字——正确记法是「印度 T+1，自某年某月起」，这样规则一变，你知道该去重读哪一格，而不是拿着过期地图找新路。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>迁移检查按钱的顺序：可交易性、税后成本、后链稳定性、制度断点，顺序不可倒。</li><li>三张表收束全课程：维度表指回各课、案例表演示顺序、失败模式表收录三种死法。</li><li>制度变更日按事件日处理：样本切段、参数重读、绩效标注生成口径。</li><li>环境常量显式化是本课程的全部产出：策略等于公式加制度假设，两者都要进台账。</li><li>出处：Harris, <em>Trading and Exchanges</em>, 2003；Foucault, Pagano and Röell, <em>Market Liquidity</em>, 2013；本课程各课所引公开规则与文献。</li></ul>',6))])}const g=l(p,[["render",m]]);export{C as __pageData,g as default};
